return {
  threat: {
    hook: "onEvent",
    eventType: "guard",
    promptOnPlayer: async (H, actor) => {
      const zone = H.zone.of(actor);
      if (!zone) return false;
      const zones = [zone, ...H.zone.adjacent(zone)].filter(value => value !== "Support");
      const action = await H.ask.one({
        title: "Goad", hint: "Place or Shift 1 Threat in your area or an adjacent area.",
        options: [{ value: "place", label: "Place" }, { value: "shift", label: "Shift" }],
        buttonChoices: true, cancelLabel: "Skip",
      });
      if (!action) return false;
      if (action === "shift") return H.threat.shift(actor, { label: "Goad: Shift", reason: "Goad" });
      const target = await H.ask.one({
        title: "Goad: Place",
        label: "Place Threat",
        options: zones.map(value => ({ value, label: value })),
        applyLabel: "Place",
      });
      if (!target) return false;
      await H.threat.place(actor, target, 1, { source: "ability", reason: "Goad" });
      return true;
    },
  },
};
